use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
fn main () -> Result < () > { let lmdfb_data = fs :: read_to_string ("lmdfb_lattice_mapping.json") ? ; let lmdfb : serde_json :: Value = serde_json :: from_str (& lmdfb_data) ? ; let mut field_reports : HashMap < i32 , FieldUsageReport > = HashMap :: new () ; if let Some (nodes) = lmdfb ["nodes"] . as_object () { for (symbol , node) in nodes { analyze_field_usage (symbol , node , & mut field_reports) ; } } let mut sorted_reports : Vec < _ > = field_reports . into_values () . collect () ; sorted_reports . sort_by (| a , b | b . total_usage_count . cmp (& a . total_usage_count)) ; println ! ("📊 Integer Field Usage Analysis") ; println ! ("===============================\n") ; for (i , report) in sorted_reports . iter () . take (15) . enumerate () { println ! ("{}. Integer: {} (Used in {} fields)" , i + 1 , report . integer_value , report . total_usage_count) ; let mut fields : Vec < _ > = report . field_usage . iter () . collect () ; fields . sort_by (| a , b | b . 1 . cmp (a . 1)) ; println ! ("   🏷️  Fields: {}" , fields . iter () . take (5) . map (| (field , count) | format ! ("{}({})" , field , count)) . collect ::< Vec < _ >> () . join (", ")) ; let mut types : Vec < _ > = report . field_types . iter () . collect () ; types . sort_by (| a , b | b . 1 . cmp (a . 1)) ; println ! ("   📝 Types: {}" , types . iter () . take (3) . map (| (t , c) | format ! ("{}({})" , t , c)) . collect ::< Vec < _ >> () . join (", ")) ; let mut contexts : Vec < _ > = report . usage_contexts . iter () . collect () ; contexts . sort_by (| a , b | b . 1 . cmp (a . 1)) ; println ! ("   🎯 Contexts: {}" , contexts . iter () . take (3) . map (| (ctx , c) | format ! ("{}({})" , ctx , c)) . collect ::< Vec < _ >> () . join (", ")) ; println ! () ; } fs :: write ("field_usage_report.json" , serde_json :: to_string_pretty (& sorted_reports) ?) ? ; println ! ("📄 Detailed report saved to: field_usage_report.json") ; Ok (()) }
}